class Song {
  constructor(title) {
    this.title = title;
  }
}

class Playlist {
  constructor() {
    this.songs = [];
  }

  addSong(title) {
    this.songs.push(new Song(title));
    return this;
  }

  [Symbol.iterator]() {
    let current = 0;
    const { songs } = this;

    return {
      next() {
        if (current < songs.length) {
          return { value: songs[current++], done: false };
        }
        return { value: undefined, done: true };
      }
    };
  }
}

